$body = '{"email":"ivan@example.com","password":"DemoPass123"}'; $r = Invoke-WebRequest -Uri http://127.0.0.1:8000/auth/login -Method Post -ContentType 'application/json' -Body $body -UseBasicParsing; $j = $r.Content | ConvertFrom-Json; $token = $j.access_token; $h = @{ Authorization = "Bearer $token"; "Content-Type" = "application/json" }; $tr = Invoke-WebRequest -Uri "http://127.0.0.1:8000/admin/transfers" -Method Post -Headers $h -Body '{"from_warehouse_id":"55555555-5555-5555-5555-555555555003","to_warehouse_id":"55555555-5555-5555-5555-555555555004","status":"draft"}' -UseBasicParsing -ErrorAction SilentlyContinue; "POST /admin/transfers status=draft: $($tr.StatusCode)"
